<script setup lang="ts">
/** 交付策略沿用唯一业务后端；CLI 卡片管理任务领取，凭据只读且不复制。 */
import { computed, ref, shallowRef, watch } from 'vue';
import type { AutomationData, AutomationSettings } from '../../../shared/hub';
import { useSource, useSourceActions } from '../../shared/api';
import { safeUrl, dateTime } from '../../shared/format';
import PageHeading from '../../shared/ui/PageHeading.vue';
import QueryState from '../../shared/ui/QueryState.vue';
import StatusPill from '../../shared/ui/StatusPill.vue';
import FullRecord from '../../shared/ui/FullRecord.vue';
import { validDeliverySettings } from './domain';
import CliExecutorCard from './CliExecutorCard.vue';
const query = useSource<AutomationData>('automation');
const config = useSource<{ baseUrl: string; hasCredentials: boolean }>('config');
const { data, error, isPending, isFetching } = query;
const form = ref<AutomationSettings>(), dirty = shallowRef(false), saving = shallowRef(false);
const actions = useSourceActions();
function reset() { if (data.value) { form.value = { ...data.value.settings, dailyTimes: [...data.value.settings.dailyTimes] }; dirty.value = false; } }
watch(data, () => { if (!dirty.value) reset(); }, { immediate: true });
const valid = computed(() => validDeliverySettings(form.value));
async function save() {
  if (!form.value || !valid.value || saving.value) return;
  const value = form.value;
  const payload = { dailyTime: value.dailyTimes[0], dailyTimes: [...value.dailyTimes], maxDispatchPerRun: value.maxDispatchPerRun, startStatus: value.startStatus, completedStatus: value.completedStatus, targetBranch: value.targetBranch, reviewer: value.reviewer, enabled: value.enabled, autoCreateCodex: value.autoCreateCodex, autoTransitionJira: value.autoTransitionJira, autoCreateMergeRequest: value.autoCreateMergeRequest };
  saving.value = true;
  try { const ok = await actions.execute('settings', payload, '确认保存自动交付设置', `这会更新当前交付工作区的实际配置。自动巡检${value.enabled ? '启用' : '暂停'}；自动创建 Codex ${value.autoCreateCodex ? '开启' : '关闭'}；自动推进 Jira ${value.autoTransitionJira ? '开启' : '关闭'}；自动创建 MR ${value.autoCreateMergeRequest ? '开启' : '关闭'}。后续调度将按这些设置运行。`); if (ok) { dirty.value = false; reset(); } } finally { saving.value = false; }
}
</script>
<template>
  <PageHeading title="交付设置" description="管理本机 CLI 执行器与交付策略；业务队列和审核记录保持唯一来源。" :loading="isFetching" @refresh="query.refetch()" />
  <CliExecutorCard />
  <QueryState :loading="isPending" :error="error" :has-data="!!data && !!form" @retry="query.refetch()"><div v-if="form && data" class="settings-grid"><div class="surface"><div class="surface-header"><div><h2>自动交付策略</h2><p>未保存的修改只保留在本页</p></div><StatusPill :value="data.settings.enabled ? 'active' : 'paused'" :label="data.settings.enabled ? '策略已启用' : '策略已暂停'" /></div><el-form class="surface-body settings-form" :disabled="saving" label-position="top" @change="dirty = true"><div class="settings-switch"><div><strong>启用自动巡检</strong><p>后端按每天指定时间巡检</p></div><el-switch v-model="form.enabled" aria-label="启用自动巡检" @change="dirty = true" /></div><el-form-item label="每日巡检时间"><div class="schedule-times"><el-time-select v-for="(_, index) in form.dailyTimes" :key="index" v-model="form.dailyTimes[index]" start="00:00" step="00:15" end="23:45" :aria-label="`巡检时间 ${index + 1}`" @change="dirty = true" /></div></el-form-item><el-form-item label="每轮最大派发数量"><el-input-number v-model="form.maxDispatchPerRun" :min="0" :precision="0" aria-label="每轮最大派发数量" @change="dirty = true" /><span class="row-secondary">0 表示不限制，与原系统一致</span></el-form-item><div class="settings-switch"><div><strong>自动创建 Codex 任务</strong><p>已授权任务由本机 Codex CLI 执行</p></div><el-switch v-model="form.autoCreateCodex" aria-label="自动创建 Codex 任务" @change="dirty = true" /></div><div class="settings-switch"><div><strong>自动推进 Jira 状态</strong><p>按原流程进入开始 / 完成状态</p></div><el-switch v-model="form.autoTransitionJira" aria-label="自动推进 Jira 状态" @change="dirty = true" /></div><div class="settings-switch"><div><strong>自动创建合并请求</strong><p>沿用目标分支与审核人配置</p></div><el-switch v-model="form.autoCreateMergeRequest" aria-label="自动创建合并请求" @change="dirty = true" /></div><div class="settings-fields"><el-form-item label="开始状态"><el-input v-model="form.startStatus" aria-label="开始状态" /></el-form-item><el-form-item label="完成状态"><el-input v-model="form.completedStatus" aria-label="完成状态" /></el-form-item><el-form-item label="目标分支"><el-input v-model="form.targetBranch" aria-label="目标分支" /></el-form-item><el-form-item label="审核人"><el-input v-model="form.reviewer" aria-label="审核人" /></el-form-item></div><el-alert v-if="!valid" title="请填写有效的时间、派发数量、状态和目标分支。" type="error" :closable="false" /><div class="settings-actions"><el-button @click="reset">恢复已保存配置</el-button><el-button type="primary" :disabled="!valid" :loading="saving" @click="save">保存交付设置</el-button></div></el-form></div><div><section class="surface"><div class="surface-header"><h2>连接与运行环境</h2></div><div class="surface-body"><dl class="settings-facts"><dt>Jira 服务</dt><dd><a :href="safeUrl(config.data.value?.baseUrl)" target="_blank">{{ config.data.value?.baseUrl || '未读取' }}</a></dd><dt>来源凭据状态</dt><dd>{{ config.error.value ? '读取失败' : config.data.value ? config.data.value.hasCredentials ? '已在原系统配置（不读取密钥）' : '原系统未配置' : '正在读取' }}</dd><dt>下次自动巡检</dt><dd>{{ dateTime(data.nextRun) }}</dd><dt>运行环境 / 浏览器</dt><dd>{{ data.settings.runtimeEnvironment || '未配置' }} / {{ data.settings.browser || '未配置' }}</dd><dt>启动命令</dt><dd>{{ data.settings.runtimeCommand || '未配置' }}</dd><dt>仓库地址</dt><dd>{{ data.settings.repositoryUrl || '未配置' }}</dd></dl></div></section><el-alert title="配置边界" description="这里只管理当前工作区的交付策略。CLI 队列在上方单独启停；打开页面不会授权合入，也不会修改 Codex 的其他自动化任务。" type="info" :closable="false" show-icon /><section class="surface settings-source"><div class="surface-header"><h2>已保存配置（只读）</h2></div><div class="surface-body"><FullRecord :value="data.settings" /></div></section></div></div></QueryState>
</template>
<style scoped>.settings-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:22px}.settings-switch{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:23px}.settings-switch strong{font-size:13px;font-weight:500}.settings-switch p{font-size:11px;color:var(--ui-muted);line-height:1.8;margin:7px 0 0}.settings-form:deep(.el-form-item__label){font-size:12px;color:var(--ui-muted)}.schedule-times,.settings-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;width:100%}.schedule-times:deep(.el-select){width:100%}.settings-actions{display:flex;gap:10px;border-top:1px solid var(--ui-border);padding-top:22px;margin-top:10px}.settings-facts{margin:0}.settings-facts dt{font-size:11px;color:var(--ui-muted);margin-top:17px}.settings-facts dt:first-child{margin-top:0}.settings-facts dd{font-size:12px;color:var(--ui-secondary);line-height:1.9;overflow-wrap:anywhere;margin:7px 0 0}.settings-source{margin-top:20px}@media(max-width:1000px){.settings-grid{grid-template-columns:1fr}}@media(max-width:500px){.settings-fields,.schedule-times{grid-template-columns:1fr}.settings-actions{flex-wrap:wrap}}</style>
